//! ⚑️ Native optional flags retain exact absent and authored false states.
use super::*;
use crate::test_source_custody;
fn close<T:Puzzle2dFlagIntent>(cursor:&mut Puzzle2dFlagPreparationCursor<T>){cursor.begin_close();for _ in 0..64{if cursor.terminal_is_empty(){return}let copy=cursor.next_close_copy_byte_demand().unwrap();let capacity=cursor.next_close_capacity_byte_demand(copy).unwrap();let release=cursor.next_close_release_byte_demand().unwrap();let depth=cursor.next_close_depth_demand().unwrap();assert!(copy+capacity+release<=4096);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:capacity,maximum_release_bytes:release,maximum_depth:depth};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);assert!(step.unwrap().progress().fits(grant));}panic!("native flag aliases did not close")}
fn law<T:Puzzle2dFlagIntent+Clone>(snapshot:&Puzzle2dSnapshot,payload:T,row:&serde_json::Value){
 assert!(std::mem::size_of::<Puzzle2dFlagPreparationCursor<T>>()<=4096);let original=serde_json::to_value(snapshot).unwrap();let mut source=test_source_custody::admit();let mut mutation=test_source_custody::admit();let grant=RetainedCloneGrant::one_payload_turn(17,64);
 let(mut cursor,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(Puzzle2dFlagPreparationCursor::<T>::default);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),RetainedCloneGrant::default()));assert_eq!(step.unwrap(),Puzzle2dFlagPreparationStep::Pending(RetainedCloneProgress::default()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 let mut plan=None;for turn in 0..100000{let permit=if turn%2==0{grant}else{RetainedCloneGrant::one_release_turn(4096,64)};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),permit));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!heap.overflowed);let step=step.unwrap();let progress=match step{Puzzle2dFlagPreparationStep::Pending(progress)|Puzzle2dFlagPreparationStep::Complete{progress,..}=>progress};assert!(progress.fits(permit));if let Puzzle2dFlagPreparationStep::Complete{plan:value,..}=step{plan=Some(value);break}}
 let plan=plan.expect("native flag plan not completed");let status=match plan.disposition{Puzzle2dFlagDisposition::Changed=>"changed",Puzzle2dFlagDisposition::NoOp=>"no-op",Puzzle2dFlagDisposition::TargetMissing=>"target-missing"};assert_eq!(status,row["status"].as_str().unwrap());assert_eq!(serde_json::to_value(plan.index).unwrap(),row["index"]);assert_eq!(plan.previous,row["index"].as_u64().map(|_|row["previous"].as_bool()));assert_eq!(cursor.take(),Some(plan));assert_eq!(cursor.take(),None);close(&mut cursor);
 for pause in [0,1,3,17]{let mut cursor=Puzzle2dFlagPreparationCursor::<T>::default();for turn in 0..pause{let permit=if turn%2==0{grant}else{RetainedCloneGrant::one_release_turn(4096,64)};if matches!(cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),permit).unwrap(),Puzzle2dFlagPreparationStep::Complete{..}){break}}close(&mut cursor);assert_eq!(cursor.take(),None)}
 let mut cursor=Puzzle2dFlagPreparationCursor::<T>::default();cursor.advance(source.borrow(snapshot),mutation.borrow(&payload),grant).unwrap();let swapped=payload.clone();assert!(cursor.advance(source.borrow(snapshot),mutation.borrow(&swapped),grant).is_err());close(&mut cursor);assert_eq!(serde_json::to_value(snapshot).unwrap(),original);test_source_custody::close(&mut source);test_source_custody::close(&mut mutation);
}
#[test]
fn history_edit_puzzle2d_borrowed_optional_flag_preparation_preserves_exact_native_first_target_and_alias_cancel(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let text=|value:&serde_json::Value|{let value=value.as_str().unwrap();match value.strip_prefix("$large:"){Some(suffix)=>PagedUtf8::<{usize::MAX}>::from(format!("{}{suffix}",corpus["control"]["largePrefix"].as_str().unwrap().repeat(corpus["control"]["largeRepeats"].as_u64().unwrap()as usize))),None=>value.into()}};
 for row in corpus["cases"].as_array().unwrap(){let mut snapshot=Puzzle2dSnapshot::default();let kind=row["kind"].as_str().unwrap();let locked=kind.ends_with("locked");for item in row["rows"].as_array().unwrap(){let flag=item["value"].as_bool();if kind.starts_with("node"){let mut node=crate::Puzzle2dNode{id:text(&item["id"]),..Default::default()};if locked{node.locked=flag}else{node.visible=flag}snapshot.nodes.push(node)}else{let mut edge=crate::Puzzle2dEdge{id:text(&item["id"]),..Default::default()};if locked{edge.locked=flag}else{edge.visible=flag}snapshot.edges.push(edge)}}let id=text(&row["mutation"]["id"]);let value=row["mutation"]["value"].as_bool();match kind{"node-locked"=>law(&snapshot,ChangeNodeLocked{id,new_locked:value},row),"node-visible"=>law(&snapshot,ChangeNodeVisible{id,new_visible:value},row),"edge-locked"=>law(&snapshot,ChangeEdgeLocked{id,new_locked:value},row),"edge-visible"=>law(&snapshot,ChangeEdgeVisible{id,new_visible:value},row),_=>unreachable!()}}
 eprintln!("[DEBUG] forty actual typed node/edge optional flag plans preserve first ID, absent/false distinction, zeroheap constructor/advance and four native alias cancellation points");
}

#[test]
fn history_edit_puzzle2d_borrowed_root_flag_preserves_literal_prior_state_and_first_native_owner(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🌟️root/🧫️fixtures/🔣️.json")).unwrap();let text=|value:&serde_json::Value|{let value=value.as_str().unwrap();match value.strip_prefix("$large:"){Some(suffix)=>PagedUtf8::<{usize::MAX}>::from(format!("{}{suffix}",corpus["control"]["largePrefix"].as_str().unwrap().repeat(corpus["control"]["largeRepeats"].as_u64().unwrap()as usize))),None=>value.into()}};
 for row in corpus["cases"].as_array().unwrap(){let mut snapshot=Puzzle2dSnapshot::default();for item in row["rows"].as_array().unwrap(){snapshot.nodes.push(crate::Puzzle2dNode{id:text(&item["id"]),root:item["value"].as_bool(),..Default::default()})}law(&snapshot,ChangeNodeRoot{id:text(&row["mutation"]["id"]),new_root:row["mutation"]["value"].as_bool()},row)}
 eprintln!("[DEBUG] ten real root flag first-native-owner plans preserve absent/false distinction, zeroheap constructor/advance and four alias cancellation points");
}

#[test]
fn history_edit_puzzle2d_borrowed_required_region_flags_preserve_literal_first_owner_and_zeroheap_cancel(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🏁️region/🧫️fixtures/🔣️.json")).unwrap();let expand=|value:&str|match value.strip_prefix("$large:"){Some(suffix)=>format!("{}{suffix}",corpus["control"]["largePrefix"].as_str().unwrap().repeat(corpus["control"]["largeRepeats"].as_u64().unwrap()as usize)),None=>value.to_owned()};
 for row in corpus["cases"].as_array().unwrap(){let mut snapshot=Puzzle2dSnapshot::default();let hidden=row["kind"]=="region-hidden";for item in row["rows"].as_array().unwrap(){let mut region=crate::Puzzle2dTargetRegion{id:expand(item["id"].as_str().unwrap()).into(),..Default::default()};if hidden{region.hidden=item["value"].as_bool().unwrap()}else{region.locked=item["value"].as_bool().unwrap()}snapshot.target_regions.push(region)}let id=expand(row["mutation"]["id"].as_str().unwrap()).into();let value=row["mutation"]["value"].as_bool().unwrap();if hidden{law(&snapshot,ChangeTargetRegionHidden{id,new_hidden:value},row)}else{law(&snapshot,ChangeTargetRegionLocked{id,new_locked:value},row)}}
 eprintln!("[DEBUG] twenty required region flags preserve first native owner, literal false/true and zeroheap native preparation/cancellation");
}
